<!-- Generated by nexa2vue: screen viewer. Lists every src/views/**/*.vue and shows the selected one. -->
<template>
  <div class="nv-layout">
    <aside class="nv-side">
      <h1>nexa2vue 화면 보기</h1>
      <input v-model="filter" class="nv-filter" type="search" placeholder="화면 검색">
      <p class="nv-count">{{ filtered.length }} / {{ screens.length }}개</p>
      <ul class="nv-list">
        <li v-for="s in filtered" :key="s.path">
          <a :href="'#/' + s.name" :class="{ active: s.name === current }">{{ s.name }}</a>
        </li>
      </ul>
    </aside>
    <main class="nv-main">
      <p v-if="!current" class="nv-hint">왼쪽 목록에서 화면을 고르세요.</p>
      <template v-else>
        <h2 class="nv-title">{{ current }}</h2>
        <p v-if="error" class="nv-error">{{ error }}</p>
        <div v-else class="nv-stage">
          <component :is="view" :key="current" />
        </div>
      </template>
    </main>
  </div>
</template>

<script setup>
import { ref, computed, shallowRef, watch, defineAsyncComponent, onErrorCaptured, onBeforeUnmount } from 'vue';

const modules = import.meta.glob('./views/**/*.vue');
const screens = Object.keys(modules)
  .sort()
  .map((path) => ({ path, name: path.replace(/^\.\/views\//, '').replace(/\.vue$/, '') }));

const filter = ref('');
const filtered = computed(() => {
  const q = filter.value.trim().toLowerCase();
  return q ? screens.filter((s) => s.name.toLowerCase().includes(q)) : screens;
});

// The selected screen lives in the URL hash (#/member/MemberList) so refresh and back work.
const current = ref('');
const view = shallowRef(null);
const error = ref('');

function readHash() {
  current.value = decodeURIComponent(location.hash.replace(/^#\/?/, ''));
}
window.addEventListener('hashchange', readHash);
onBeforeUnmount(() => window.removeEventListener('hashchange', readHash));
readHash();

watch(current, (name) => {
  error.value = '';
  const screen = screens.find((s) => s.name === name);
  view.value = screen ? defineAsyncComponent(modules[screen.path]) : null;
  if (name && !screen) error.value = `화면을 찾을 수 없습니다: ${name}`;
}, { immediate: true });

// A broken screen shows its error here instead of blanking the whole viewer.
onErrorCaptured((err) => {
  error.value = `화면 실행 오류: ${err && err.message ? err.message : err}`;
  return false;
});
</script>

