.nv-side { width: 280px; flex: none; display: flex; flex-direction: column; border-right: 1px solid #ddd; background: #f7f7f8; padding: 12px; box-sizing: border-box; }
.nv-side h1 { font-size: 16px; margin: 0 0 8px; }
.nv-filter { width: 100%; box-sizing: border-box; padding: 6px 8px; border: 1px solid #ccc; border-radius: 4px; }
.nv-count { margin: 6px 0; font-size: 12px; color: #666; }
.nv-list { list-style: none; margin: 0; padding: 0; overflow: auto; flex: 1; }
.nv-list a { display: block; padding: 4px 6px; border-radius: 4px; color: inherit; text-decoration: none; font-size: 13px; word-break: break-all; }
.nv-list a:hover { background: #e9e9ec; }
.nv-list a.active { background: #409eff; color: #fff; }
.nv-main { flex: 1; overflow: auto; padding: 16px; box-sizing: border-box; }
.nv-title { font-size: 14px; margin: 0 0 12px; color: #555; font-weight: normal; }
.nv-hint { color: #666; }
